/* AHV — ONE compact family header (owner decision 26 Sep 2026, HEADER-TAKEOVER-OWNER-DECISION.md;
 * EF-04 + EF-25). On every page of a site-tree family (window.AHV_SECTION_NAV.family, generated by
 * tools/build-section-nav.mjs) the family navigation REPLACES the primary navigation inside the SAME
 * header row — nothing is stacked under it:
 *   · desktop: the five primary links give way to one "In this section · <family> ▾" control;
 *   · phone: the hamburger opens the same panel;
 *   · the panel holds the family tree (current page marked) AND the main menu (home, primary links,
 *     contact, search), so home / global navigation, the language switcher and Book stay one tap away
 *     in the same surface;
 *   · the old left rail / in-content "In this section" block is not drawn (no duplicate menus);
 *   · the programme finder's filter rows collapse behind a "Filters (n)" control (user-expanded,
 *     not sticky) with Clear / Done;
 *   · no bottom Call / Enquire / Free-consult bar on family pages (owner: essential actions stay in
 *     the header).
 * Works on design pages (shared chrome component), native Next.js pages (snapshot chrome) and every
 * locale (labels via window.__AHV_T, hrefs via window.AHV_LOCAL_PATHS). Idempotent on re-mounts.
 * Consent, forms and tracking are untouched. */
(function () {
  "use strict";
  var D = window.AHV_SECTION_NAV;
  if (!D || !D.family || !D.sections) return;
  var root = document.getElementById("ahv-design-root");
  var route = (root && root.getAttribute("data-ahv-route")) || location.pathname;
  var fam = D.family[route];
  if (!fam) return;
  var section = D.sections[fam.section];
  if (!section) return;
  var LP = window.AHV_LOCAL_PATHS || null;
  function lp(p) { return (LP && LP[p]) || p; }
  function T(s) { var d = window.__AHV_T; return (d && d[s]) || s; }
  function esc(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); }
  var html = document.documentElement;
  html.setAttribute("data-ahv-fh", fam.section);

  function onPath(node) {
    if (node.path) return fam.crumbs.indexOf(node.path) >= 0;
    for (var i = 0; i < (node.children || []).length; i++) if (onPath(node.children[i])) return true;
    return false;
  }
  var bid = 0;
  function list(nodes) {
    var h = '<ul class="ahv-fh-list">';
    for (var i = 0; i < nodes.length; i++) {
      var n = nodes[i], here = onPath(n), cur = n.path === route, kids = n.children && n.children.length, id = "ahv-fh-b" + (++bid);
      h += '<li><div class="ahv-fh-row">';
      if (n.link) h += '<a href="' + esc(lp(n.path)) + '"' + (cur ? ' aria-current="page"' : "") + ">" + esc(n.label) + "</a>";
      else h += '<span class="ahv-fh-plain">' + esc(n.label) + "</span>";
      if (kids) h += '<button type="button" class="ahv-fh-toggle" aria-controls="' + id + '" aria-expanded="' + (here ? "true" : "false") + '" aria-label="' + esc(n.label) + '"><span aria-hidden="true">' + (here ? "−" : "+") + "</span></button>";
      h += "</div>";
      if (kids) h += '<div id="' + id + '" class="ahv-fh-kids"' + (here ? "" : " hidden") + ">" + list(n.children) + "</div>";
      h += "</li>";
    }
    return h + "</ul>";
  }

  // ---- the main menu: taken from the page's own chrome (already localized), never invented
  function mainMenuLinks() {
    var seen = {}, out = [];
    function add(a) {
      var href = a.getAttribute("href") || "";
      // internal pages only (root-relative or this site's absolute URL); no tel/mailto/booking engine
      if (!(/^\/(?!\/)/.test(href) || /^https?:\/\/(www\.)?ayurvedichealingvillage\.com(\/|$)/.test(href))) return;
      var key = href.replace(/^https?:\/\/(www\.)?ayurvedichealingvillage\.com/, "");
      if (seen[key]) return; seen[key] = 1;
      var label = (a.textContent || "").replace(/\s+/g, " ").replace(/^\d+\s*/, "").replace(/[→›]\s*$/, "").trim();
      if (label) out.push({ href: href, label: label });
    }
    var drawer = document.querySelector("[data-ahv-drawer] nav, [data-ahv-sc-panel] nav, [data-ahv-drawer], [data-ahv-sc-panel]");
    if (drawer) { var a = drawer.querySelectorAll("a[href]"); for (var i = 0; i < a.length; i++) if (!a[i].closest(".ahv-lang, .ahv-lang-list") && !a[i].hasAttribute("hreflang")) add(a[i]); }
    if (out.length < 4) {
      var nav = document.querySelector("header nav[data-ahv-fh-primary]");
      if (nav) { var b = nav.querySelectorAll("a[href]"); for (var j = 0; j < b.length; j++) add(b[j]); }
    }
    return out;
  }

  var panel = null, openBtn = null;
  function buildPanel() {
    if (panel && document.body.contains(panel)) return panel;
    bid = 0;
    panel = document.createElement("div");
    panel.id = "ahv-fh-panel";
    panel.className = "ahv-fh-panel";
    panel.hidden = true;
    var hub = section.hub ? '<a class="ahv-fh-hub" href="' + esc(lp(section.hub)) + '"' + (section.hub === route ? ' aria-current="page"' : "") + ">" + esc(T("Overview")) + "</a>" : "";
    var menu = mainMenuLinks().map(function (l) { return '<li><a href="' + esc(l.href) + '">' + esc(l.label) + "</a></li>"; }).join("");
    panel.innerHTML =
      '<div class="ahv-fh-panel-in">' +
        '<div class="ahv-fh-head"><div><span class="ahv-fh-kicker">' + esc(T("In this section")) + '</span><span class="ahv-fh-title">' + esc(section.label) + "</span></div>" +
        '<button type="button" class="ahv-fh-close" aria-label="' + esc(T("Close")) + '"><span aria-hidden="true">✕</span></button></div>' +
        '<div class="ahv-fh-cols">' +
          '<nav class="ahv-fh-family" aria-label="' + esc(T("In this section") + ": " + section.label) + '">' + hub + list(section.items) + "</nav>" +
          '<nav class="ahv-fh-main" aria-label="' + esc(T("Main menu")) + '"><span class="ahv-fh-kicker">' + esc(T("Main menu")) + '</span><ul class="ahv-fh-list">' + menu +
            '<li><a href="' + esc(lp("/search/")) + '">' + esc(T("Search")) + "</a></li></ul></nav>" +
        "</div>" +
      "</div>";
    if (!panel.querySelector('.ahv-fh-family [aria-current="page"]')) {
      var h1 = document.querySelector("main h1, h1");
      var here = document.createElement("a"); here.href = location.pathname; here.setAttribute("aria-current", "page");
      here.className = "ahv-fh-here"; here.textContent = h1 ? h1.textContent.trim() : route;
      panel.querySelector(".ahv-fh-family").appendChild(here);
    }
    panel.addEventListener("click", function (e) {
      var t = e.target.closest ? e.target.closest("button") : null;
      if (!t) return;
      if (t.classList.contains("ahv-fh-close")) { close(true); return; }
      if (t.classList.contains("ahv-fh-toggle")) {
        var kids = panel.querySelector("#" + t.getAttribute("aria-controls"));
        var ex = t.getAttribute("aria-expanded") !== "true";
        t.setAttribute("aria-expanded", String(ex)); t.firstElementChild.textContent = ex ? "−" : "+";
        if (kids) kids.hidden = !ex;
      }
    });
    document.body.appendChild(panel);
    return panel;
  }
  function place() {
    if (!panel || panel.hidden || !openBtn) return;
    var hdr = openBtn.closest("header");
    var top = hdr ? Math.max(0, Math.round(hdr.getBoundingClientRect().bottom)) : 64;
    panel.style.top = top + "px";
    panel.style.maxHeight = "calc(100vh - " + top + "px)";
  }
  function open(btn) {
    buildPanel(); openBtn = btn; panel.hidden = false; place();
    var all = document.querySelectorAll("[data-ahv-fh-btn]"); for (var i = 0; i < all.length; i++) all[i].setAttribute("aria-expanded", "true");
    html.setAttribute("data-ahv-fh-open", "");
    var cur = panel.querySelector('.ahv-fh-family [aria-current="page"]') || panel.querySelector("a,button");
    if (cur) { try { cur.focus({ preventScroll: true }); } catch (e) { cur.focus(); } if (cur.scrollIntoView) cur.scrollIntoView({ block: "nearest" }); }
  }
  function close(returnFocus) {
    if (!panel || panel.hidden) return;
    panel.hidden = true; html.removeAttribute("data-ahv-fh-open");
    var all = document.querySelectorAll("[data-ahv-fh-btn]"); for (var i = 0; i < all.length; i++) all[i].setAttribute("aria-expanded", "false");
    if (returnFocus && openBtn) openBtn.focus();
  }
  document.addEventListener("keydown", function (e) { if (e.key === "Escape" && panel && !panel.hidden) { e.preventDefault(); close(true); } });
  document.addEventListener("click", function (e) {
    var b = e.target.closest ? e.target.closest("[data-ahv-fh-btn]") : null;
    if (b) { e.preventDefault(); if (panel && !panel.hidden) close(false); else open(b); return; }
    if (panel && !panel.hidden && !panel.contains(e.target)) close(false);
  });
  window.addEventListener("resize", place);

  // ---- header surgery: mark the chrome's own parts, add ONE control per header variant
  function isHamburger(b) {
    if (b.classList.contains("ahv-lang-btn") || b.getAttribute("aria-haspopup") === "dialog" || b.hasAttribute("data-ahv-fh-btn")) return false;
    var s = b.children; if (s.length !== 3) return false;
    for (var i = 0; i < 3; i++) if (s[i].tagName !== "SPAN") return false;
    return true;
  }
  function deskButton() {
    var b = document.createElement("button");
    b.type = "button"; b.className = "ahv-fh-btn ahv-fh-btn-desk";
    b.setAttribute("data-ahv-fh-btn", "desk"); b.setAttribute("aria-expanded", "false"); b.setAttribute("aria-controls", "ahv-fh-panel");
    b.innerHTML = '<span class="ahv-fh-kicker">' + esc(T("In this section")) + '</span><span class="ahv-fh-name">' + esc(section.label) + '</span><span class="ahv-fh-chev" aria-hidden="true"></span>';
    return b;
  }
  function phoneButton() {
    var b = document.createElement("button");
    b.type = "button"; b.className = "ahv-fh-btn ahv-fh-btn-phone";
    b.setAttribute("data-ahv-fh-btn", "phone"); b.setAttribute("aria-expanded", "false"); b.setAttribute("aria-controls", "ahv-fh-panel");
    b.setAttribute("aria-label", T("Menu") + ": " + section.label);
    b.innerHTML = '<span aria-hidden="true"></span><span aria-hidden="true"></span><span aria-hidden="true"></span>';
    return b;
  }
  function headers() {
    var hs = document.querySelectorAll("header");
    for (var i = 0; i < hs.length; i++) {
      var h = hs[i];
      if (h.closest("main") || h.closest(".ahv-fh-panel")) continue;
      // desktop variant: a nav with >= 4 links (the primary navigation)
      var navs = h.querySelectorAll("nav");
      for (var k = 0; k < navs.length; k++) {
        var n = navs[k];
        if (n.closest(".ahv-lang") || n.querySelectorAll("a[href]").length < 4) continue;
        n.setAttribute("data-ahv-fh-primary", "");
        if (!n.parentNode.querySelector("[data-ahv-fh-btn='desk']")) n.parentNode.insertBefore(deskButton(), n);
      }
      // phone variant: the hamburger
      var bs = h.querySelectorAll("button");
      for (var j = 0; j < bs.length; j++) {
        if (!isHamburger(bs[j])) continue;
        bs[j].setAttribute("data-ahv-fh-hamburger", "");
        if (!bs[j].parentNode.querySelector("[data-ahv-fh-btn='phone']")) bs[j].parentNode.insertBefore(phoneButton(), bs[j]);
      }
    }
  }

  // ---- the bottom Call / Enquire / Free-consult bar is not shown on family pages
  function ctaBars() {
    var tels = document.querySelectorAll('a[href^="tel:"]');
    for (var i = 0; i < tels.length; i++) {
      var el = tels[i].parentElement, hops = 0;
      while (el && el !== document.body && hops < 4) {
        var st = el.getAttribute("style") || "";
        if (/position:\s*fixed/.test(st) && /bottom:\s*0/.test(st) && el.querySelector('a[href*="online-consultation"]') && el.querySelector('a[href*="enquiry-form"]')) { el.setAttribute("data-ahv-cta-bar", ""); break; }
        el = el.parentElement; hops++;
      }
    }
  }

  // ---- programme finder: filters behind a user-controlled toggle, not a sticky multi-row bar
  function finder() {
    var nav = document.querySelector("nav[data-ahv-finder-search]");
    if (!nav) return;
    nav.setAttribute("data-ahv-fh-finder", "");
    var bar = nav.nextElementSibling && nav.nextElementSibling.classList && nav.nextElementSibling.classList.contains("ahv-fh-filterbar") ? nav.nextElementSibling : null;
    if (!bar) {
      bar = document.createElement("div");
      bar.className = "ahv-fh-filterbar";
      bar.innerHTML = '<button type="button" class="ahv-fh-filters" aria-expanded="false"></button>' +
        '<button type="button" class="ahv-fh-clear" hidden>' + esc(T("Clear filters")) + "</button>";
      nav.parentNode.insertBefore(bar, nav.nextSibling);
      bar.addEventListener("click", function (e) {
        var b = e.target.closest ? e.target.closest("button") : null;
        if (!b) return;
        if (b.classList.contains("ahv-fh-filters")) {
          var open = !nav.hasAttribute("data-ahv-fh-open");
          if (open) nav.setAttribute("data-ahv-fh-open", ""); else nav.removeAttribute("data-ahv-fh-open");
          count();
          if (open) { var first = nav.querySelector('[role="group"] button'); if (first) first.focus(); }
        } else if (b.classList.contains("ahv-fh-clear")) {
          // drive the finder's own controls: "Any" on duration / budget, un-press the condition chip
          var groups = nav.querySelectorAll('[role="group"]');
          for (var g = 0; g < groups.length; g++) {
            var kind = groupKind(groups[g]), btns = groups[g].querySelectorAll("button");
            if (kind === "labelled" && btns[0] && btns[0].getAttribute("aria-pressed") !== "true") btns[0].click();
            if (kind === "chips") for (var c = 0; c < btns.length; c++) if (btns[c].getAttribute("aria-pressed") === "true") btns[c].click();
          }
          setTimeout(count, 60);
        }
      });
    }
    count();
  }
  // group kinds, structural (labels are translated): currency = the three ₹ $ € buttons;
  // labelled = Duration / Budget (a visible <span> label, first button is "Any"); chips = conditions
  function groupKind(g) {
    var btns = g.querySelectorAll("button");
    if (btns.length === 3 && /^[₹$€]$/.test((btns[0].textContent || "").trim())) return "currency";
    for (var i = 0; i < g.children.length; i++) if (g.children[i].tagName === "SPAN") return "labelled";
    return "chips";
  }
  // active filters = a pressed condition chip + any non-"Any" duration / budget (currency is a preference)
  function count() {
    var nav = document.querySelector("nav[data-ahv-fh-finder]");
    var bar = document.querySelector(".ahv-fh-filterbar");
    if (!nav || !bar) return;
    var n = 0, groups = nav.querySelectorAll('[role="group"]');
    for (var g = 0; g < groups.length; g++) {
      var kind = groupKind(groups[g]), btns = groups[g].querySelectorAll("button");
      if (kind === "currency") continue;
      for (var b = 0; b < btns.length; b++) if (btns[b].getAttribute("aria-pressed") === "true" && !(kind === "labelled" && b === 0)) n++;
    }
    var open = nav.hasAttribute("data-ahv-fh-open");
    var fb = bar.querySelector(".ahv-fh-filters");
    var label = (open ? T("Hide filters") : T("Filters")) + (n ? " (" + n + ")" : "");
    if (fb.textContent !== label) fb.textContent = label;
    fb.setAttribute("aria-expanded", open ? "true" : "false");
    bar.querySelector(".ahv-fh-clear").hidden = !n;
  }

  var scheduled = false;
  function pass() { scheduled = false; try { headers(); ctaBars(); finder(); } catch (e) { /* never break the page */ } }
  function schedule() { if (scheduled) return; scheduled = true; setTimeout(pass, 0); }
  if (window.MutationObserver) new MutationObserver(schedule).observe(document.body || document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ["aria-pressed"] });
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", schedule); else schedule();
  window.addEventListener("load", schedule);
})();
